#' Experimental D3 Cutoff and ROC Explorer (Python)
#'
#' 
#' @param data .
#' @param marker .
#' @param reference .
#' @param positive .
#' @param direction .
#' @param criterion .
#' @param cutoff .
#' @param fpCost .
#' @param fnCost .
#' @param ciMethod .
#' @param ciWidth .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$explorer} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$counts} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$metrics} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$staticDotplot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$rocSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$staticROC} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$counts$asDF}
#'
#' \code{as.data.frame(results$counts)}
#'
#' @export
pyd3cutoff <- function(
    data,
    marker = NULL,
    reference = NULL,
    positive,
    direction = "ge",
    criterion = "errors",
    cutoff = "",
    fpCost = 1,
    fnCost = 4,
    ciMethod = "exact",
    ciWidth = 95,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyd3cutoff requires jmvcore to be installed (restart may be required)")

    if ( ! missing(marker)) marker <- jmvcore::resolveQuo(jmvcore::enquo(marker))
    if ( ! missing(reference)) reference <- jmvcore::resolveQuo(jmvcore::enquo(reference))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(marker), marker, NULL),
            `if`( ! missing(reference), reference, NULL))

    for (v in reference) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pyd3cutoffOptions$new(
        marker = marker,
        reference = reference,
        positive = positive,
        direction = direction,
        criterion = criterion,
        cutoff = cutoff,
        fpCost = fpCost,
        fnCost = fnCost,
        ciMethod = ciMethod,
        ciWidth = ciWidth,
        showConsole = showConsole)

    analysis <- pyd3cutoffClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

